source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python -c "
import wandb
api = wandb.Api()

r300 = api.run('xiaoyucorynne-/cost-verify-agent-rl/ozyniycy')
h = r300.history(samples=500, pandas=False)
for i, row in enumerate(h):
    # Filter to relevant metrics
    relevant = {}
    for k, v in row.items():
        if v is not None and ('success' in k or 'response_length' in k or 'kl' in k or 'pass' in k or 'action_is_valid' in k or 'num_actions' in k or 'reward' in k or 'return' in k or k == '_step'):
            relevant[k] = v
    if relevant:
        print(f'Row {i}: {relevant}')
"
